{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana Rent Stabilization Ordinance annual rent cap","requirement":"A landlord may not raise residential rent by more than the lower of 3% per year or 80% of the 12-month change in CPI; no increase is allowed if CPI is negative. Exemptions and a fair-return petition process apply.","key_value":"lower of 3% per year or 80% of 12-month CPI; no increase if CPI negative","coverage_conditions":"Residential rental units, including covered mobile home spaces. Does not apply to residential buildings constructed after February 1, 1995, or mobile home spaces offered for rent after January 1, 1990.","applicability":{"built_on_or_before":"1995-02-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Exempts mobile home spaces offered for rent after 1990-01-01."},"exemptions":"Residential buildings constructed after February 1, 1995; mobile home spaces offered for rent after January 1, 1990.","penalty":null,"effective_date":"2021-11-19","citation":"Rent Stabilization Ordinance","quoted_span":"Increase in residential rents are limited to the lower of 3% per year, or 80% of the percent change in the Consumer Price Index over the most recent 12-month period. If the CPI is negative, no rent increase is permitted.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana Just Cause Eviction Ordinance","requirement":"After 30 days of tenancy, a landlord may not terminate without just cause stated in written notice. No-fault terminations require 3 months' relocation assistance or waiver of final 3 months' rent. Certain property types are exempt.","key_value":"30 days' tenancy; 3 months' relocation assistance or rent waiver","coverage_conditions":"Residential tenancies after 30 days. Exempts housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; and other shared living quarters.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Exempts housing produced in the last 15 years; deed-restricted affordable; transient, institutional, dormitory, shared quarters."},"exemptions":"Housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; and other shared living quarters.","penalty":null,"effective_date":"2021-11-19","citation":"Just Cause Eviction Ordinance","quoted_span":"After 30 days, an owner shall not terminate a tenancy without just cause, which shall be stated in a written notice.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
